              ...(newPrice !== null ? { price: newPrice } : {}),
              ...(p.change.quantity !== null ? { quantity: p.change.quantity } : {}),
            },
          ],
          proration_date: p.start + p.change.offset,
          ...(p.change.proration_behavior !== null
            ? { proration_behavior: p.change.proration_behavior }
