510	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
511	  const parts = req.path.split("/").filter((s) => s !== "");
512	  if (parts[0] !== "v1") return null;
513	  const [, a, b, c, d] = parts;
514	  const m = req.method;
515	
516	  if (a === "test_helpers" && b === "test_clocks") {
517	    if (m === "POST" && c === undefined) {
518	      const id = mint(state, "clock");
519	      const t = num(p.frozen_time) ?? 0;
520	      state.clocks[id] = { id, frozen_time: t, created: t };
521	      return ok(clockJson(state, id));
522	    }
523	    const clock = c !== undefined ? get(state.clocks, c) : undefined;
524	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
525	    if (m === "GET") return ok(clockJson(state, c));
526	    if (m === "POST" && d === "advance") {
527	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
528	      return ok(clockJson(state, c));
529	    }
530	  }
531	  if (a === "products" && m === "POST" && b === undefined) {
532	    const id = mint(state, "prod");
533	    state.products[id] = { id, name: str(p.name) ?? "" };
534	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
535	  }
536	  if (a === "prices" && m === "POST" && b === undefined) {
537	    const id = mint(state, "price");
538	    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
539	    state.prices[id] = {
540	      id,
541	      product: str(p.product) ?? "",
542	      unit_amount: num(p.unit_amount) ?? 0,
543	      currency: str(p.currency) ?? "usd",
544	      interval,
545	      created: latestClockTime(state),
546	    };
547	    return ok(priceJson(state, id));
548	  }
549	  if (a === "prices" && m === "GET" && b !== undefined) {
550	    return get(state.prices, b) ? ok(priceJson(state, b)) : missing("price", b);
551	  }
552	  if (a === "subscription_items") return subscriptionItems(state, req, p, b);
553	  if (a === "coupons" && m === "POST" && b === undefined) {
554	    const id = mint(state, "coupon");
555	    const coupon = {
556	      id,
557	      percent_off: num(p.percent_off),
558	      amount_off: num(p.amount_off),
559	      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
560	      created: latestClockTime(state),
561	    };
562	    state.coupons[id] = coupon;
563	    return ok(couponJson(coupon));
564	  }
565	  if (a === "customers") {
566	    if (m === "POST" && b === undefined) {
567	      const id = mint(state, "cus");
568	      const clock = str(p.test_clock);
569	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
570	      const pmToken = str(p.payment_method);
571	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
572	      const cus = {
573	        id,
574	        clock,
575	        default_payment_method: pm,
576	        created: now,
577	        balance: 0,
578	        currency: null,
579	        invoice_prefix: invoicePrefix(state.n),
580	        preferred_locales: arr(p.preferred_locales).map((x) => str(x) ?? ""),
581	      };
582	      state.customers[id] = cus;
583	      return ok(customerJson(state, cus));
584	    }
585	    const cus = b !== undefined ? get(state.customers, b) : undefined;
586	    if (!cus || b === undefined) return missing("customer", b ?? "");
587	    if (m === "POST" && c === undefined) {
588	      const dpm = str(obj(p.invoice_settings).default_payment_method);
589	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
590	    }
591	    return ok(customerJson(state, cus));
592	  }
593	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
594	    const id = paymentMethodFrom(state, b, str(p.customer));
595	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
596	  }
597	  if (a === "subscriptions") {
598	    if (m === "POST" && b === undefined) return createSubscription(state, p);
599	    if (m === "GET" && b === undefined) return listSubscriptions(state, p);
600	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
601	    if (!sub || b === undefined) return missing("subscription", b ?? "");
602	    if (m === "GET") return ok(expandedSubscription(state, sub, p));
603	    if (m === "DELETE") {
604	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
605	      return ok(subscriptionJson(state, sub, false));
606	    }
607	    if (m === "POST") {
608	      const res = updateSubscription(state, sub, p);
609	      return res.status === 200 ? ok(expandedSubscription(state, sub, p)) : res;
610	    }
611	  }
612	  if (a === "invoices") {
613	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
614	    if (m === "POST" && b === undefined) return createInvoice(state, p);
615	    if (m === "GET" && b === "upcoming") return fail(400, UPCOMING_GONE);
616	    if (m === "GET" && b === undefined) return listInvoices(state, p);
617	    if (m === "GET" && b !== undefined) {
618	      const inv = get(state.invoices, b);
619	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
620	    }
621	  }
622	  if (a === "invoiceitems") {
623	    if (m === "GET" && b === undefined) return listInvoiceItems(state, p);
624	    if (m === "POST" && b === undefined) return createInvoiceItem(state, p);
625	    if (m === "GET" && b !== undefined) {
626	      const ii = get(state.invoice_items, b);
627	      // The message names the object as "Invoice Item" and adds the mode (ITM-02).
628	      return ii
