691	// INV-02: POST /v1/invoices makes a draft (billing_reason manual). With
692	// pending_invoice_items_behavior=include it takes the customer's pending invoice items. With
693	// auto_advance it is finalized and paid an hour after creation (next_payment_attempt); without,
694	// it stays a draft.
695	function createInvoice(state: State, p: Params): CloneResponse {
696	  const customer = str(p.customer) ?? "";
697	  const cus = get(state.customers, customer);
698	  if (!cus) return missing("customer", customer);
699	  const now = customerNow(state, customer);
700	  const auto = bool(p.auto_advance);
701	  const id = mint(state, "in");
702	  const lines: Line[] = [];
703	  if (str(p.pending_invoice_items_behavior) === "include") {
704	    for (const ii of Object.values(state.invoice_items)) {
705	      if (ii.customer !== customer || ii.invoice !== null) continue;
706	      ii.invoice = id;
707	      lines.push({ ...ii.line, id: mint(state, "il") });
708	    }
709	  }
710	  const inv: Invoice = {
711	    id,
712	    customer,
713	    subscription: null,
714	    lines,
715	    discounts: [],
716	    total_discount_amounts: [],
717	    billing_reason: "manual",
718	    status: "draft",
719	    created: now,
720	    // Observed: from creation to one month later (dev-v4-draft-*; it is also the subscription's
721	    // period end there, so which of the two it follows is not pinned).
722	    period_start: now,
723	    period_end: addIntervals(now, "month", 1),
724	    attempt_count: 0,
725	    amount_paid: 0,
726	    auto_advance: auto,
727	    next_payment_attempt: auto ? now + 3600 : null,
728	    proration_date: null,
729	    retries: [],
730	    starting_balance: 0,
731	    deferred: 0,
732	    finalized_at: null,
733	    paid_at: null,
734	    manual: true,
735	  };
736	  state.invoices[id] = inv;
737	  return ok(invoiceJson(state, inv, false));
738	}
