740	// An 8-letter invoice prefix, deterministic (recorded as noise).
741	function invoicePrefix(n: number): string {
742	  let x = n * 2654435761;
743	  let s = "";
744	  for (let i = 0; i < 8; i += 1) {
745	    s += String.fromCharCode(65 + (x % 26));
746	    x = Math.floor(x / 26) + 7 * (i + 1);
747	  }
748	  return s;
749	}
