106	// Pending invoice items (prorations) of a subscription, moved onto an invoice.
107	export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
108	  const out: Line[] = [];
109	  for (const ii of Object.values(state.invoice_items)) {
110	    if (ii.subscription !== sub.id || ii.invoice !== null) continue;
111	    ii.invoice = invoice;
112	    out.push({ ...ii.line, id: mint(state, "il") });
113	  }
114	  return out;
115	}
