117	function renew(state: State, sub: Subscription): void {
118	  const start = sub.period_end;
119	  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
120	  const end = periodAt(sub.anchor, interval, start)[1];
121	  const id = mint(state, "in");
122	  const pending = takePending(state, sub, id);
123	  const lines: Line[] = sub.items.map((it) => {
124	    const p = priceOf(state, it.price);
125	    return {
126	      id: mint(state, "il"),
127	      amount: p.unit_amount * it.quantity,
128	      description: recurringDescription(state, it.price, it.quantity),
129	      period: { start, end },
130	      price: it.price,
131	      quantity: it.quantity,
132	      proration: false,
133	      discountable: true,
134	      discount_amounts: [],
135	      subscription_item: it.id,
136	      invoice_item: null,
137	      credited: null,
138	      unit_amount_decimal: String(p.unit_amount),
139	    };
140	  });
141	  const active = sub.discounts.filter((d) => {
142	    const s = specOf(state, d);
143	    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
144	  });
145	  const specs = specsOf(state, active);
146	  const alloc = allocate(
147	    lines.map((l) => l.amount),
148	    specs,
149	  );
150	  lines.forEach((l, i) => {
151	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
152	  });
153	  spendOnce(state, specs, alloc);
154	  sub.items.forEach((it, i) => {
155	    const l = lines[i];
156	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
157	  });
158	  const all = [...pending, ...lines];
159	  const inv: Invoice = {
160	    id,
161	    customer: sub.customer,
162	    subscription: sub.id,
163	    lines: all,
164	    discounts: specs.map((s) => s.id),
165	    total_discount_amounts: specs.map((s, k) => ({
166	      discount: s.id,
167	      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
168	    })),
169	    billing_reason: "subscription_cycle",
170	    status: "draft",
171	    created: start,
172	    period_start: sub.period_start,
173	    period_end: start,
174	    attempt_count: 0,
175	    amount_paid: 0,
176	    auto_advance: true,
177	    next_payment_attempt: start + HOUR,
178	    proration_date: null,
179	    retries: [],
180	    starting_balance: 0,
181	    deferred: 0,
182	    finalized_at: null,
183	    paid_at: null,
184	    manual: false,
185	  };
186	  // The customer balance moves onto the renewal invoice; a credit beyond its total stays.
187	  const cus = get(state.customers, sub.customer);
188	  if (cus) {
189	    inv.starting_balance = cus.balance;
190	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
191	  }
192	  state.invoices[id] = inv;
193	  sub.latest_invoice = id;
194	  sub.period_start = start;
195	  sub.period_end = end;
196	  if (sub.status === "trialing") sub.status = "active";
197	}
