199	function attempt(state: State, inv: Invoice, at: number): void {
200	  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
201	  const due = amountDue(inv);
202	  inv.finalized_at ??= at;
203	  if (due === 0 || deferSmall(state, inv)) {
204	    inv.status = "paid";
205	    inv.paid_at = at;
206	    inv.next_payment_attempt = null;
207	    if (inv.manual) inv.auto_advance = false;
208	    return;
209	  }
210	  inv.attempt_count += 1;
211	  if (!failing(state, inv.customer)) {
212	    inv.status = "paid";
213	    inv.paid_at = at;
214	    inv.amount_paid = due;
215	    inv.next_payment_attempt = null;
216	    if (inv.manual) inv.auto_advance = false;
217	    if (sub?.status === "past_due") sub.status = "active";
218	    return;
219	  }
220	  inv.status = "open";
221	  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
222	  const next = inv.retries.shift();
223	  inv.next_payment_attempt = next ?? null;
224	  if (sub && sub.status !== "canceled") sub.status = "past_due";
225	}
226	
227	// Runs every event of the clock's customers up to `to`, in time order.
228	export function advanceClock(state: State, clock: Clock, to: number): void {
229	  const customers = new Set(
230	    Object.values(state.customers)
231	      .filter((c) => c.clock === clock.id)
232	      .map((c) => c.id),
233	  );
234	  for (let guard = 0; guard < 1000; guard += 1) {
235	    const events: { at: number; run: () => void }[] = [];
236	    const consider = (at: number, run: () => void): void => {
237	      if (at <= to) events.push({ at, run });
238	    };
239	    for (const sub of Object.values(state.subscriptions)) {
240	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
241	      const cancelAt = sub.cancel_at;
242	      if (cancelAt !== null && cancelAt <= sub.period_end) {
243	        consider(cancelAt, () => {
244	          sub.status = "canceled";
245	          sub.ended_at = cancelAt;
246	        });
247	        continue;
248	      }
249	      consider(sub.period_end, () => {
250	        if (sub.cancel_at_period_end) {
251	          sub.status = "canceled";
252	          sub.ended_at = sub.period_end;
253	        } else {
254	          renew(state, sub);
255	        }
256	      });
257	    }
258	    for (const inv of Object.values(state.invoices)) {
259	      if (!customers.has(inv.customer)) continue;
260	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
261	        const at = inv.next_payment_attempt;
262	        if (at !== null) {
263	          consider(at, () => {
264	            attempt(state, inv, at);
265	          });
266	        }
267	      }
268	    }
269	    // The earliest event first; ties keep discovery order (subscriptions before invoices).
270	    const chosen = events.reduce<{ at: number; run: () => void } | null>(
271	      (best, e) => (best === null || e.at < best.at ? e : best),
272	      null,
273	    );
274	    if (chosen === null) break;
275	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
276	    chosen.run();
277	  }
278	  clock.frozen_time = to;
279	}
280	
281	export function cancelNow(
282	  state: State,
283	  sub: Subscription,
284	  prorate: boolean,
285	  invoiceNow: boolean,
286	): void {
287	  const now = nowFor(state, sub.customer);
288	  if (prorate && now < sub.period_end) {
289	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
290	    if (invoiceNow) {
291	      const id = mint(state, "in");
292	      const pending = takePending(state, sub, id);
293	      const lines: Line[] = [
294	        ...pending,
295	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
296	      ];
297	      state.invoices[id] = {
298	        id,
299	        customer: sub.customer,
300	        subscription: sub.id,
301	        lines,
302	        discounts: [],
303	        total_discount_amounts: [],
304	        billing_reason: "subscription_cycle",
305	        status: "draft",
306	        created: now,
307	        period_start: sub.period_start,
308	        period_end: now,
309	        attempt_count: 0,
310	        amount_paid: 0,
311	        auto_advance: false,
312	        next_payment_attempt: null,
313	        proration_date: null,
314	        retries: [],
315	        starting_balance: 0,
316	        deferred: 0,
317	        finalized_at: null,
318	        paid_at: null,
319	        manual: false,
320	      };
321	      sub.latest_invoice = id;
322	    } else {
323	      for (const l of credits) addPending(state, sub, l, now);
324	    }
325	  }
326	  sub.status = "canceled";
327	  sub.ended_at = now;
328	  sub.canceled_at ??= now;
329	  sub.cancellation_reason = "cancellation_requested";
330	  sub.cancel_at_period_end = false;
331	  sub.cancel_at = null;
332	}
