215	const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
216	
217	// Deterministic IDs: the same calls after a reset mint the same IDs.
218	export function mint(state: State, prefix: string): string {
219	  state.n += 1;
220	  const n = state.n;
221	  let x = n * 7919 + 104729;
222	  let s = "";
223	  while (s.length < 14) {
224	    s = (ALPHABET[x % 62] ?? "0") + s;
225	    x = Math.floor(x / 62) + n * 31;
226	  }
227	  // Stripe IDs start with an upper-case letter or digit after the prefix; keep one fixed shape.
228	  return `${prefix}_1${s}`;
229	}
230	
231	export function get<T>(table: Record<string, T>, id: string): T | undefined {
232	  return Object.hasOwn(table, id) ? table[id] : undefined;
233	}
234	
235	// The clock time a customer lives on (its test clock), or the subscription's creation time.
236	export function nowFor(state: State, customer: string): number {
237	  const c = get(state.customers, customer);
238	  const clock = c?.clock ? get(state.clocks, c.clock) : undefined;
239	  return clock ? clock.frozen_time : Math.floor(Date.now() / 1000);
240	}
