139	// ---------------------------------------------------------------- change plan
140	
141	export interface ItemChange {
142	  id: string;
143	  price: string | null;
144	  quantity: number | null;
145	}
146	
147	export type Behavior = "create_prorations" | "none" | "always_invoice";
148	
149	export interface PlannedItem {
150	  id: string;
151	  price: string;
152	  quantity: number;
153	}
154	
155	export interface Plan {
156	  // Proration lines, without IDs.
157	  prorations: Omit<Line, "id" | "invoice_item">[];
158	  // The discounts each proration line actually carries (for its discount list).
159	  own: DiscSpec[][];
160	  // Per proration line: how many discounts a credit line carried (null for a charge).
161	  carried: (number | null)[];
162	  items: PlannedItem[];
163	  // Per planned item: its interval and the end of its current (possibly new) period.
164	  intervals: Interval[];
165	  ends: number[];
166	  // Items whose price or quantity changes.
167	  changed: string[];
168	  // Discounts of the new state (a once coupon passed to the preview included).
169	  discounts: string[];
170	  // Once coupons that took something from the remaining-time charges (spent there).
171	  spent: string[];
172	  immediate: boolean;
173	  // A classic interval change restarts the cycle at the clock time.
174	  reset: boolean;
175	  period_start: number;
176	  // When the preview invoice falls: the earliest item period end (or the reset period's end).
177	  period_end: number;
178	  anchor: number;
179	  proration_date: number;
180	  now: number;
181	}
182	
183	export interface PlanError {
184	  message: string;
185	  param: string | null;
186	}
187	
188	export interface PlanInput {
189	  changes: ItemChange[];
190	  proration_date: number | null;
191	  behavior: Behavior | null;
192	  // Discount IDs replacing the subscription's, or null to keep them.
193	  discounts: string[] | null;
194	  now: number;
195	}
196	
197	interface Carried {
198	  spec: DiscSpec;
199	  amount: number;
200	}
201	
202	// Every discount on the line that billed the period, those it got nothing from included.
203	function billedDiscounts(state: State, billed: Billed | null): Carried[] {
204	  if (!billed) return [];
205	  return billed.discounts
206	    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
207	    .filter((x): x is Carried => x.spec !== undefined);
208	}
209	
210	// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
211	// item got on the invoice that billed the period (PRO-01, DSC-04).
212	export function creditLine(
213	  state: State,
214	  sub: Subscription,
215	  it: SubItem,
216	  prd: number,
217	): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[]; carried: number } {
218	  const oldPrice = priceOf(state, it.price);
219	  const P = sub.period_end - sub.period_start;
220	  const r = sub.period_end - prd;
221	  const b = oldPrice.unit_amount * it.quantity;
222	  const all = billedDiscounts(state, it.billed);
223	  const carried = all.filter((c) => c.amount !== 0);
224	  let credit: number;
225	  let applied: DiscSpec[];
226	  if (sub.billing_mode === "classic") {
227	    // Classic (DSC-04, pass 6): every discount of the billed line, in subscription order, applies
228	    // to the credited item on its own (an amount-off in full, a percent-off on what is left),
229	    // whatever share it got on the billing invoice, 0 included; then the net is prorated.
230	    const D = allocate(
231	      [b],
232	      all.map((c) => c.spec),
233	    ).reduce((a, x) => a + (x[0] ?? 0), 0);
234	    credit = -roundRatio((b - D) * r, P);
235	    applied = all.map((c) => c.spec);
236	  } else {
237	    // Flexible: a carried discount whose prorated amount rounds to 0 is not applied (DSC-08).
238	    const prorated = carried.map((c) => roundRatio(c.amount * r, P));
239	    credit = -(roundRatio(b * r, P) - prorated.reduce((a, x) => a + x, 0));
240	    applied = carried.filter((_, k) => (prorated[k] ?? 0) !== 0).map((c) => c.spec);
241	  }
242	  return {
243	    line: {
244	      amount: credit,
245	      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
246	      period: { start: prd, end: sub.period_end },
247	      price: it.price,
248	      quantity: it.quantity,
249	      proration: true,
250	      discountable: false,
251	      discount_amounts: [],
252	      subscription_item: it.id,
253	      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
254	      unit_amount_decimal: null,
255	    },
256	    own: applied,
257	    // Discounts on the billed line, those it got nothing from included (DSC-07).
258	    carried: all.length,
259	  };
260	}
