449	// The invoice a plan produces: now (immediate) or at the next renewal (prorations plus the next
450	// full period of every item whose period ends then).
451	export function draftFromPlan(
452	  state: State,
453	  sub: Subscription,
454	  plan: Plan,
455	  ids: { line: () => string; item: () => string },
456	  mode: Subscription["billing_mode"],
457	): Draft {
458	  // An active once coupon (DSC-05, pass 5) that took something from a remaining-time charge is
459	  // spent there: off the invoice and off the renewal lines. Otherwise it is on the invoice and
460	  // discounts the renewal. An immediate invoice lists it either way (at 0 there).
461	  const top = plan.discounts.filter((id) => {
462	    const s = specOf(state, id);
463	    if (!s) return false;
464	    return !s.once || plan.immediate || !plan.spent.includes(id);
465	  });
466	  const topSpecs = specsOf(state, top);
467	  const lines: Line[] = plan.prorations.map((p) => ({
468	    ...p,
469	    id: ids.line(),
470	    invoice_item: ids.item(),
471	  }));
472	  const recurring: Line[] = [];
473	  if (plan.reset) {
474	    plan.items.forEach((it, i) => {
475	      if (!plan.changed.includes(it.id)) return;
476	      const end = plan.ends[i] ?? plan.period_end;
477	      recurring.push(recurringLine(state, it, plan.period_start, end, ids.line()));
478	    });
479	  } else if (!plan.immediate) {
480	    const at = plan.period_end;
481	    plan.items.forEach((it, i) => {
482	      const iv = plan.intervals[i];
483	      if (plan.ends[i] !== at || iv === undefined) return;
484	      const next = periodAt(plan.anchor, iv, at)[1];
485	      recurring.push(recurringLine(state, it, at, next, ids.line()));
486	    });
487	  }
488	  const alloc = allocate(
489	    recurring.map((l) => l.amount),
490	    topSpecs,
491	  );
492	  recurring.forEach((l, i) => {
493	    l.discount_amounts = topSpecs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
494	  });
495	  lines.forEach((l, i) => {
496	    const mine = (plan.own[i] ?? []).map((s) => s.id);
497	    const carried = plan.carried[i] ?? null;
498	    // Observed only (no documented rule): which discounts a proration line lists, at 0.
499	    let list: string[];
500	    if (mode === "classic") list = top;
501	    else if (plan.immediate) {
502	      if (carried === null) list = mine;
503	      // DSC-07, as the dev cases pin it: see NOTES.md, pass 4.
504	      else if (top.length === 0) list = [];
505	      else if (carried === 0) list = top;
506	      else if (mine.length === 0) list = [];
507	      else if (carried === 1) list = mine;
508	      else list = top;
509	    } else if (top.length > 0) list = top.slice(0, 1);
510	    else list = mine;
511	    l.discount_amounts = list.map((discount) => ({ discount, amount: 0 }));
512	  });
513	  const all = [...lines, ...recurring];
514	  const tda = top.map((discount) => ({
515	    discount,
516	    amount: all.reduce(
517	      (a, l) =>
518	        a +
519	        l.discount_amounts.filter((d) => d.discount === discount).reduce((x, d) => x + d.amount, 0),
520	      0,
521	    ),
