524	  return {
525	    lines: all,
526	    discounts: top,
527	    total_discount_amounts: tda,
528	    created: immediate ? plan.now : plan.period_end,
529	    period_start: immediate ? plan.now : sub.period_start,
530	    period_end: immediate ? plan.now : plan.period_end,
531	    immediate,
532	  };
533	}
