560	// The smallest amount the account charges (INV-01): dev-t2-f-left55 is not charged, left56 is.
561	export const MIN_CHARGE = 56;
562	
563	// What an invoice asks for: its total plus the starting balance, less an amount deferred to the
564	// customer balance because it was below the minimum charge.
565	export function amountDue(inv: {
566	  lines: Line[];
567	  total_discount_amounts: DiscountAmount[];
568	  starting_balance: number;
569	  deferred: number;
570	}): number {
571	  const { total } = totals(inv.lines, inv.total_discount_amounts);
572	  return Math.max(0, total + inv.starting_balance) - inv.deferred;
573	}
574	
575	// Charges below the minimum are not attempted: the amount goes to the customer balance.
576	export function deferSmall(state: State, inv: Invoice): boolean {
577	  const due = amountDue(inv);
578	  if (due <= 0 || due >= MIN_CHARGE) return false;
579	  inv.deferred += due;
580	  const c = get(state.customers, inv.customer);
581	  if (c) c.balance += due;
582	  inv.status = "paid";
583	  inv.next_payment_attempt = null;
584	  return true;
585	}
586	
587	export function totals(lines: Line[], tda: DiscountAmount[]) {
588	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
589	  const discount = tda.reduce((a, d) => a + d.amount, 0);
590	  return { subtotal, total: subtotal - discount };
591	}
